import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to efficiently 
    test for membership of items with a defined false positive rate.

    The optimal size of the bit array and the number of hash functions 
    are calculated based on the expected number of items and the 
    desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_hash_count()

        self.bit_array = [False] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal bit array size."""
        size = -(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)
        return math.ceil(size)

    def _calculate_hash_count(self) -> int:
        """Calculate the optimal number of hash functions."""
        hash_count = (self.size / self.expected_items) * math.log(2)
        return math.ceil(hash_count)

    def _get_hashes(self, item: str) -> list:
        """Generate a set of hash values for the given item."""
        hash_values = []
        for i in range(self.hash_count):
            hash_instance = hashlib.md5((item + str(i)).encode()).hexdigest()
            hash_index = int(hash_instance, 16) % self.size
            hash_values.append(hash_index)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_index in self._get_hashes(item):
            self.bit_array[hash_index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for hash_index in self._get_hashes(item):
            if not self.bit_array[hash_index]:
                return False
        return True

