            hash_index = int(hash_instance, 16) % self.size
            hash_values.append(hash_index)
        return hash_values

    def _set_bit(self, index: int) -> None:
        """Set a bit in the bit array at the specified index."""
        self.bit_array[index // 32] |= (1 << (index % 32))

    def _get_bit(self, index: int) -> bool:
        """Check if a bit in the bit array is set at the specified index."""
        return (self.bit_array[index // 32] & (1 << (index % 32))) != 0

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_index in self._get_hashes(item):
            self._set_bit(hash_index)

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for hash_index in self._get_hashes(item):
            if not self._get_bit(hash_index):
                return False
        return True

